examples.code:
message = "My name is Sam and my phone is 555 0101"
private = ["Sam"]
safe = []
for w in message.split():
    if w in private or w.isdigit():
        safe.append("[hidden]")
    else:
        safe.append(w)
print(" ".join(safe))

